'use strict';

const express = require('express');
const { z } = require('zod');

const shipmentSchema = z
  .object({
    recipient: z.object({
      name: z.string().min(1),
      street: z.string().min(1),
      city: z.string().min(1),
      zip: z.string().min(1),
    }),
    weight_kg: z.number().min(0.01).max(1000),
    express: z.boolean(),
  })
  .strict(); // reject unknown top-level keys

function buildApp() {
  const app = express();
  app.use(express.json());

  app.post('/shipments', (req, res) => {
    const result = shipmentSchema.safeParse(req.body);
    if (!result.success) {
      const issues = result.error.issues.map((issue) => ({
        path: issue.path.join('.'),
        message: issue.message,
      }));
      return res.status(400).json({ error: { code: 'validation_error', issues } });
    }
    return res.status(201).json({ id: 's_' + Date.now().toString(36), shipment: result.data });
  });

  return app;
}

module.exports = { buildApp };

