'use strict';

const { test, describe } = require('node:test');
const assert = require('node:assert/strict');
const request = require('supertest');
const { buildApp } = require('../src/app');

const app = buildApp();

const validPayload = {
  recipient: {
    name: 'Ada Lovelace',
    street: '12 Analytical Way',
    city: 'London',
    zip: 'NW1 6XE',
  },
  weight_kg: 2.5,
  express: true,
};

describe('POST /shipments', () => {
  test('returns 201 for a valid payload', async () => {
    const res = await request(app).post('/shipments').send(validPayload);
    assert.equal(res.status, 201);
    assert.ok(res.body.shipment);
    assert.equal(res.body.shipment.recipient.name, 'Ada Lovelace');
  });

  test('rejects out-of-range weight_kg and reports dotted path "weight_kg"', async () => {
    const res = await request(app)
      .post('/shipments')
      .send({ ...validPayload, weight_kg: 1000.01 });
    assert.equal(res.status, 400);
    assert.equal(res.body.error.code, 'validation_error');
    const paths = res.body.error.issues.map((i) => i.path);
    assert.ok(
      paths.includes('weight_kg'),
      `expected "weight_kg" in issues, got ${JSON.stringify(paths)}`
    );
    assert.equal(typeof res.body.error.issues[0].message, 'string');
  });

  test('rejects missing recipient.zip and reports dotted path "recipient.zip"', async () => {
    const payload = JSON.parse(JSON.stringify(validPayload));
    delete payload.recipient.zip;
    const res = await request(app).post('/shipments').send(payload);
    assert.equal(res.status, 400);
    assert.equal(res.body.error.code, 'validation_error');
    const paths = res.body.error.issues.map((i) => i.path);
    assert.ok(
      paths.includes('recipient.zip'),
      `expected "recipient.zip" in issues, got ${JSON.stringify(paths)}`
    );
  });

  test('rejects non-boolean express and reports dotted path "express"', async () => {
    const res = await request(app)
      .post('/shipments')
      .send({ ...validPayload, express: 'yes' });
    assert.equal(res.status, 400);
    assert.equal(res.body.error.code, 'validation_error');
    const paths = res.body.error.issues.map((i) => i.path);
    assert.ok(
      paths.includes('express'),
      `expected "express" in issues, got ${JSON.stringify(paths)}`
    );
  });

  test('rejects extra unknown top-level keys', async () => {
    const res = await request(app)
      .post('/shipments')
      .send({ ...validPayload, priority_level: 'high' });
    assert.equal(res.status, 400);
    assert.equal(res.body.error.code, 'validation_error');
    const paths = res.body.error.issues.map((i) => i.path);
    assert.ok(
      paths.includes('priority_level'),
      `expected "priority_level" in issues, got ${JSON.stringify(paths)}`
    );
  });
});

